INSERT INTO public.schools (legacy_id,name,area,latitude,longitude,description,school_types,programs,strengths,foreign_support_status,languages,international_support_level,pro_yoga_supported,featured,priority_rank,admin_recommended,google_place_id,website_url,verified,payload,is_published) VALUES ('s1','渋谷ウェルネスヨガアカデミー','渋谷',35.658,139.7016,'初心者の方でも安心して継続しやすい導線を整えた、渋谷エリアの上質な総合スクールです。少人数制クラス、資格取得サポート、プロYoga対応、国際対応まで一貫した学習環境を提供しています。',ARRAY['ヨガスタジオ','養成スクール','オンラインスクール']::text[],ARRAY['通常レッスン','体験レッスン','指導者養成','プロYoga対策']::text[],ARRAY['初心者に強い','資格取得に強い','国際連携あり','インド政府公認プロYoga対応']::text[],'積極的に受け入れ',ARRAY['日本語','英語','中国語']::text[],'国際資格対応',true,false,0,false,NULL,NULL,false,'{"id":"s1","name":"渋谷ウェルネスヨガアカデミー","type":"school","area":"渋谷","lat":35.658,"lng":139.7016,"description":"初心者の方でも安心して継続しやすい導線を整えた、渋谷エリアの上質な総合スクールです。少人数制クラス、資格取得サポート、プロYoga対応、国際対応まで一貫した学習環境を提供しています。","schoolTypes":["ヨガスタジオ","養成スクール","オンラインスクール"],"programs":["通常レッスン","体験レッスン","指導者養成","プロYoga対策"],"strengths":["初心者に強い","資格取得に強い","国際連携あり","インド政府公認プロYoga対応"],"foreignSupportStatus":"積極的に受け入れ","languages":["日本語","英語","中国語"],"internationalSupportLevel":"国際資格対応","proYogaSupported":true,"featured":false,"priorityRank":0,"adminRecommended":false}'::jsonb,true) ON CONFLICT (legacy_id) DO UPDATE SET name=EXCLUDED.name,area=EXCLUDED.area,latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,description=EXCLUDED.description,school_types=EXCLUDED.school_types,programs=EXCLUDED.programs,strengths=EXCLUDED.strengths,foreign_support_status=EXCLUDED.foreign_support_status,languages=EXCLUDED.languages,international_support_level=EXCLUDED.international_support_level,pro_yoga_supported=EXCLUDED.pro_yoga_supported,featured=EXCLUDED.featured,priority_rank=EXCLUDED.priority_rank,admin_recommended=EXCLUDED.admin_recommended,payload=EXCLUDED.payload,is_published=true;
INSERT INTO public.schools (legacy_id,name,area,latitude,longitude,description,school_types,programs,strengths,foreign_support_status,languages,international_support_level,pro_yoga_supported,featured,priority_rank,admin_recommended,google_place_id,website_url,verified,payload,is_published) VALUES ('s2','青山アライメントヨガスクール','青山',35.6665,139.7138,'少人数制で姿勢改善と肩こり改善を丁寧に学べる、青山らしい落ち着いた空気感のスクールです。継続プログラムを通じて、基礎から安心して通い続けたい方に選ばれています。',ARRAY['ヨガスタジオ']::text[],ARRAY['通常レッスン','体験レッスン','ワークショップ']::text[],ARRAY['少人数制','解剖学重視','本格指導']::text[],'一部対応',ARRAY['日本語','英語']::text[],'在日外国人対応',false,false,0,false,NULL,NULL,false,'{"id":"s2","name":"青山アライメントヨガスクール","type":"school","area":"青山","lat":35.6665,"lng":139.7138,"description":"少人数制で姿勢改善と肩こり改善を丁寧に学べる、青山らしい落ち着いた空気感のスクールです。継続プログラムを通じて、基礎から安心して通い続けたい方に選ばれています。","schoolTypes":["ヨガスタジオ"],"programs":["通常レッスン","体験レッスン","ワークショップ"],"strengths":["少人数制","解剖学重視","本格指導"],"foreignSupportStatus":"一部対応","languages":["日本語","英語"],"internationalSupportLevel":"在日外国人対応","proYogaSupported":false,"featured":false,"priorityRank":0,"adminRecommended":false}'::jsonb,true) ON CONFLICT (legacy_id) DO UPDATE SET name=EXCLUDED.name,area=EXCLUDED.area,latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,description=EXCLUDED.description,school_types=EXCLUDED.school_types,programs=EXCLUDED.programs,strengths=EXCLUDED.strengths,foreign_support_status=EXCLUDED.foreign_support_status,languages=EXCLUDED.languages,international_support_level=EXCLUDED.international_support_level,pro_yoga_supported=EXCLUDED.pro_yoga_supported,featured=EXCLUDED.featured,priority_rank=EXCLUDED.priority_rank,admin_recommended=EXCLUDED.admin_recommended,payload=EXCLUDED.payload,is_published=true;
INSERT INTO public.schools (legacy_id,name,area,latitude,longitude,description,school_types,programs,strengths,foreign_support_status,languages,international_support_level,pro_yoga_supported,featured,priority_rank,admin_recommended,google_place_id,website_url,verified,payload,is_published) VALUES ('s3','銀座プロヨガスクール','銀座',35.6712,139.7635,'資格取得サポートとプロYoga対応を軸に据えた、銀座の教育特化型スクールです。ややフォーマルで信頼感のある指導体制が整い、継続的に専門性を高めたい方に適しています。',ARRAY['養成スクール']::text[],ARRAY['指導者養成','プロYoga対策','ヨガ検定3級・2級対策','ヨガマネージャー講座']::text[],ARRAY['資格取得に強い','本格指導','哲学重視']::text[],'一部対応',ARRAY['日本語','英語']::text[],'国際資格対応',true,false,0,false,NULL,NULL,false,'{"id":"s3","name":"銀座プロヨガスクール","type":"school","area":"銀座","lat":35.6712,"lng":139.7635,"description":"資格取得サポートとプロYoga対応を軸に据えた、銀座の教育特化型スクールです。ややフォーマルで信頼感のある指導体制が整い、継続的に専門性を高めたい方に適しています。","schoolTypes":["養成スクール"],"programs":["指導者養成","プロYoga対策","ヨガ検定3級・2級対策","ヨガマネージャー講座"],"strengths":["資格取得に強い","本格指導","哲学重視"],"foreignSupportStatus":"一部対応","languages":["日本語","英語"],"internationalSupportLevel":"国際資格対応","proYogaSupported":true,"featured":false,"priorityRank":0,"adminRecommended":false}'::jsonb,true) ON CONFLICT (legacy_id) DO UPDATE SET name=EXCLUDED.name,area=EXCLUDED.area,latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,description=EXCLUDED.description,school_types=EXCLUDED.school_types,programs=EXCLUDED.programs,strengths=EXCLUDED.strengths,foreign_support_status=EXCLUDED.foreign_support_status,languages=EXCLUDED.languages,international_support_level=EXCLUDED.international_support_level,pro_yoga_supported=EXCLUDED.pro_yoga_supported,featured=EXCLUDED.featured,priority_rank=EXCLUDED.priority_rank,admin_recommended=EXCLUDED.admin_recommended,payload=EXCLUDED.payload,is_published=true;
INSERT INTO public.schools (legacy_id,name,area,latitude,longitude,description,school_types,programs,strengths,foreign_support_status,languages,international_support_level,pro_yoga_supported,featured,priority_rank,admin_recommended,google_place_id,website_url,verified,payload,is_published) VALUES ('s4','表参道インターナショナルヨガスタジオ','表参道',35.6655,139.7111,'英語対応・外国人対応を備えた、表参道の洗練された国際対応スクールです。少人数制クラスと継続プログラムにより、リラックス系から専門的な学びまで安心して続けられます。',ARRAY['ヨガスタジオ','地域コミュニティ型']::text[],ARRAY['通常レッスン','体験レッスン','イベント開催']::text[],ARRAY['国際連携あり','リラックス重視','地域密着']::text[],'積極的に受け入れ',ARRAY['日本語','英語','イタリア語']::text[],'外国人向けクラスあり',false,false,0,false,NULL,NULL,false,'{"id":"s4","name":"表参道インターナショナルヨガスタジオ","type":"school","area":"表参道","lat":35.6655,"lng":139.7111,"description":"英語対応・外国人対応を備えた、表参道の洗練された国際対応スクールです。少人数制クラスと継続プログラムにより、リラックス系から専門的な学びまで安心して続けられます。","schoolTypes":["ヨガスタジオ","地域コミュニティ型"],"programs":["通常レッスン","体験レッスン","イベント開催"],"strengths":["国際連携あり","リラックス重視","地域密着"],"foreignSupportStatus":"積極的に受け入れ","languages":["日本語","英語","イタリア語"],"internationalSupportLevel":"外国人向けクラスあり","proYogaSupported":false,"featured":false,"priorityRank":0,"adminRecommended":false}'::jsonb,true) ON CONFLICT (legacy_id) DO UPDATE SET name=EXCLUDED.name,area=EXCLUDED.area,latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,description=EXCLUDED.description,school_types=EXCLUDED.school_types,programs=EXCLUDED.programs,strengths=EXCLUDED.strengths,foreign_support_status=EXCLUDED.foreign_support_status,languages=EXCLUDED.languages,international_support_level=EXCLUDED.international_support_level,pro_yoga_supported=EXCLUDED.pro_yoga_supported,featured=EXCLUDED.featured,priority_rank=EXCLUDED.priority_rank,admin_recommended=EXCLUDED.admin_recommended,payload=EXCLUDED.payload,is_published=true;
