INSERT INTO public.schools (legacy_id,name,area,latitude,longitude,description,school_types,programs,strengths,foreign_support_status,languages,international_support_level,pro_yoga_supported,featured,priority_rank,admin_recommended,google_place_id,website_url,verified,payload,is_published) VALUES ('s10','浅草ハーモニーヨガスクール','浅草',35.711,139.7965,'浅草らしい開かれた雰囲気の中で、外国人対応と国際交流を自然に取り入れたスクールです。体験から継続受講までつながる導線があり、リラックス重視で安心して通えます。',ARRAY['地域コミュニティ型','ヨガスタジオ']::text[],ARRAY['体験レッスン','通常レッスン','イベント開催']::text[],ARRAY['リラックス重視','国際連携あり','地域密着']::text[],'積極的に受け入れ',ARRAY['日本語','英語','イタリア語']::text[],'観光客対応',false,false,0,false,NULL,NULL,false,'{"id":"s10","name":"浅草ハーモニーヨガスクール","type":"school","area":"浅草","lat":35.711,"lng":139.7965,"description":"浅草らしい開かれた雰囲気の中で、外国人対応と国際交流を自然に取り入れたスクールです。体験から継続受講までつながる導線があり、リラックス重視で安心して通えます。","schoolTypes":["地域コミュニティ型","ヨガスタジオ"],"programs":["体験レッスン","通常レッスン","イベント開催"],"strengths":["リラックス重視","国際連携あり","地域密着"],"foreignSupportStatus":"積極的に受け入れ","languages":["日本語","英語","イタリア語"],"internationalSupportLevel":"観光客対応","proYogaSupported":false,"featured":false,"priorityRank":0,"adminRecommended":false}'::jsonb,true) ON CONFLICT (legacy_id) DO UPDATE SET name=EXCLUDED.name,area=EXCLUDED.area,latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,description=EXCLUDED.description,school_types=EXCLUDED.school_types,programs=EXCLUDED.programs,strengths=EXCLUDED.strengths,foreign_support_status=EXCLUDED.foreign_support_status,languages=EXCLUDED.languages,international_support_level=EXCLUDED.international_support_level,pro_yoga_supported=EXCLUDED.pro_yoga_supported,featured=EXCLUDED.featured,priority_rank=EXCLUDED.priority_rank,admin_recommended=EXCLUDED.admin_recommended,payload=EXCLUDED.payload,is_published=true;